//! The rate floor — the price below which working makes your situation worse.
//!
//! `viable` says what a month has to cover. This says what an HOUR has to earn to cover it, and it
//! exists because the two expensive mistakes in selling your time are both failures of arithmetic
//! rather than of nerve: taking underpriced work out of urgency, and not knowing which work is worth
//! the hours it costs.
//!
//! # Four things that make a naive rate roughly half of a real one
//!
//! 1. **Billable hours are not working hours.** Somebody working forty hours a week sells perhaps
//!    twenty to twenty-five; the rest is finding the work, quoting it, invoicing it, chasing the
//!    invoice, and revisions nobody is paying for. Dividing by hours WORKED is the single largest
//!    error here and it produces a floor about half of the true one.
//! 2. **Fifty-two weeks is a lie.** Holidays, illness, and the gaps between contracts are unpaid.
//! 3. **Contract income is not salary.** Self-employment tax, cover an employer used to provide,
//!    equipment, software, accounting — all of it comes out of the same number.
//! 4. **The month that has to be covered is the WORST one**, not the average, for exactly the reason
//!    `viable` measures on the worst month: a rate that clears the median misses the month with the
//!    annual renewal in it, and that month is a missed payment.
//!
//! Every one of these pushes the same direction, so getting them wrong is never conservative.
use crate::money::{money, Currency, Money};
use crate::viable::{Tier, ViableIncome};

pub struct RateInputs {
    /// Hours a week you can REALISTICALLY SELL. Not hours you can work.
    ///
    /// There is no default, for the same reason `runway` has none for discretionary spending: a
    /// number guessed here silently halves the answer.
    pub billable_hours_per_week: f64,
    /// Weeks a year you actually bill. The default is 46, not 52 — holidays, illness and the gaps
    /// between contracts are real and unpaid, and pricing as though they are not is how a year
    /// comes up six weeks short.
    pub working_weeks_per_year: f64,
    /// The fraction of gross that never reaches you: self-employment tax, income tax, whatever
    /// applies where you are.
    ///
    /// THIS IS A PLACEHOLDER AND NOT ADVICE. It is jurisdiction-specific and it is not something
    /// this can know — set it from what you actually pay. The default is deliberately a round
    /// number so it reads as an assumption rather than a calculation.
    pub tax_fraction: f64,
    /// Monthly costs of being self-employed that a job would have absorbed — health cover,
    /// equipment, software, accounting, insurance.
    pub overheads_monthly: Money,
}

impl RateInputs {
    pub fn new(billable_hours_per_week: f64, currency: Currency) -> Self {
        RateInputs { billable_hours_per_week, working_weeks_per_year: 46.0, tax_fraction: 0.25, overheads_monthly: money(0, currency) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct TierRate {
    pub tier: Tier,
    /// What this tier costs in its WORST month.
    pub monthly_need: Money,
    /// That need plus overheads, grossed up for what never reaches you.
    pub must_bill_monthly: Money,
    /// The rate below which working leaves you short.
    pub hourly: Money,
    /// Eight billable hours. A day rate is what most work is actually quoted at.
    pub day_rate: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct RateFloor {
    pub currency: Currency,
    pub billable_hours_per_month: f64,
    pub tiers: Vec<TierRate>,
    /// The one to quote: the rate that keeps everything CURRENT, which is the line below which new
    /// damage starts.
    pub headline: TierRate,
    /// The absolute floor — what cannot lapse. Below this, working is not solving the problem.
    pub floor: TierRate,
    pub assumptions: Vec<String>,
    pub warnings: Vec<String>,
}

/// Round UP. A rate floor rounded down is a rate below your floor.
fn ceil_div(numerator: f64, denominator: f64) -> i64 {
    if denominator <= 0.0 {
        return 0;
    }
    (numerator / denominator).ceil() as i64
}

/// What an hour has to earn, tier by tier.
///
/// Returns an error rather than a number when the inputs cannot support one — a rate floor computed
/// from a refused projection is a confident number resting on nothing.
pub fn rate_floor(v: &ViableIncome, inputs: &RateInputs) -> Result<RateFloor, String> {
    let currency = v.currency;
    if inputs.billable_hours_per_week <= 0.0 {
        return Err("billable hours must be greater than zero — how many hours a week can you actually SELL? Not hours you can work: somebody working forty sells perhaps twenty to twenty-five, and the rest is finding the work, quoting it, invoicing it and chasing payment".to_string());
    }
    if inputs.working_weeks_per_year <= 0.0 || inputs.working_weeks_per_year > 52.0 {
        return Err(format!("{} working weeks is not a year", inputs.working_weeks_per_year));
    }
    if inputs.tax_fraction < 0.0 || inputs.tax_fraction >= 1.0 {
        return Err(format!("a tax fraction of {} leaves nothing to live on — it is a fraction, so 0.25 is 25%", inputs.tax_fraction));
    }
    if inputs.overheads_monthly.currency != currency {
        return Err(format!("overheads are in {} but the ladder is in {}", inputs.overheads_monthly.currency, currency));
    }

    let billable_hours_per_month = inputs.billable_hours_per_week * inputs.working_weeks_per_year / 12.0;
    let keep = 1.0 - inputs.tax_fraction;

    let mut warnings: Vec<String> = Vec::new();
    if inputs.tax_fraction == 0.0 {
        warnings.push("tax was given as zero — contract income is not salary, and a floor that ignores what never reaches you is too low by exactly that fraction".to_string());
    }
    if inputs.overheads_monthly.minor == 0 {
        warnings.push("overheads were given as zero — health cover, equipment, software and accounting all come out of this same number when nobody else is paying them".to_string());
    }
    if inputs.billable_hours_per_week > 30.0 {
        warnings.push(format!(
            "{} billable hours a week is a high number to sustain — it is not the same as working {} hours, and if the real figure is lower every rate below is too low",
            inputs.billable_hours_per_week, inputs.billable_hours_per_week
        ));
    }
    if v.gaps.is_none() {
        warnings.push("no income projection was compared against this, so nothing here knows how much of the floor you already clear".to_string());
    }

    let build = |t: &crate::viable::TierRequirement| -> TierRate {
        let need = t.worst_month.minor + inputs.overheads_monthly.minor;
        let gross = need as f64 / keep;
        let hourly = ceil_div(gross, billable_hours_per_month);
        TierRate {
            tier: t.tier,
            monthly_need: t.worst_month,
            must_bill_monthly: money(gross.ceil() as i64, currency),
            hourly: money(hourly, currency),
            day_rate: money(hourly * 8, currency),
        }
    };

    let tiers: Vec<TierRate> = v.tiers.iter().map(build).collect();
    let headline = tiers.iter().find(|t| t.tier == Tier::Current).cloned().ok_or("the ladder has no `current` tier")?;
    let floor = tiers.iter().find(|t| t.tier == Tier::Survival).cloned().ok_or("the ladder has no `survival` tier")?;

    let assumptions = vec![
        format!(
            "{} billable hours a week over {} working weeks — {:.0} billable hours a month. Billable, not worked.",
            inputs.billable_hours_per_week, inputs.working_weeks_per_year, billable_hours_per_month
        ),
        format!("{:.0}% of gross never reaches you, so every rate is grossed up by that.", inputs.tax_fraction * 100.0),
        "Measured on each tier's WORST month, not its average — the same month `viable` measures, for the same reason.".to_string(),
        "Rounded UP at every step: a rate floor rounded down is a rate below your floor.".to_string(),
    ];

    Ok(RateFloor { currency, billable_hours_per_month, tiers, headline, floor, assumptions, warnings })
}

#[derive(Debug, Clone, PartialEq)]
pub struct OfferVerdict {
    /// The rate being offered.
    pub offered: Money,
    pub tier: Tier,
    /// Billable hours a month this offer needs to reach that tier.
    pub hours_needed: f64,
    /// Hours actually available in a month.
    pub hours_available: f64,
    /// Whether the offer can reach the tier AT ALL, at any achievable number of hours.
    pub reachable: bool,
    pub why: String,
}

/// What an offered rate would actually have to be worked to reach a tier.
///
/// THE FUNCTION THAT STOPS UNDERPRICED WORK. An offer below the floor is not merely a smaller
/// number — for a low enough rate there is no number of hours in a month that reaches the tier, and
/// working harder cannot fix it. Saying that plainly is the difference between negotiating and
/// grinding.
pub fn assess_offer(f: &RateFloor, offered: Money, tier: Tier) -> Result<OfferVerdict, String> {
    if offered.currency != f.currency {
        return Err(format!("the offer is in {} but the floor is in {}", offered.currency, f.currency));
    }
    let t = f.tiers.iter().find(|x| x.tier == tier).ok_or_else(|| format!("no `{}` tier", tier.label()))?;
    if offered.minor <= 0 {
        return Err("an offered rate of zero or less is not an offer".to_string());
    }
    let hours_needed = t.must_bill_monthly.minor as f64 / offered.minor as f64;
    let reachable = hours_needed <= f.billable_hours_per_month;
    let why = if reachable {
        format!(
            "{:.0} of your {:.0} billable hours a month reaches {} — it leaves {:.0} hours for everything else",
            hours_needed,
            f.billable_hours_per_month,
            tier.label(),
            f.billable_hours_per_month - hours_needed
        )
    } else {
        format!(
            "reaching {} at this rate needs {:.0} billable hours a month and you have {:.0} — working harder cannot close that, only a higher rate or a lower tier can",
            tier.label(),
            hours_needed,
            f.billable_hours_per_month
        )
    };
    Ok(OfferVerdict { offered, tier, hours_needed, hours_available: f.billable_hours_per_month, reachable, why })
}

/// One sentence, in the terms the question gets asked in.
pub fn summarise(f: &RateFloor) -> String {
    format!(
        "{} an hour keeps everything current, {} an hour is the floor below which working is not solving the problem — at {:.0} billable hours a month",
        crate::money::format_minor(f.headline.hourly.minor),
        crate::money::format_minor(f.floor.hourly.minor),
        f.billable_hours_per_month
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::viable::{TierRequirement, ViableIncome};

    // SYNTHETIC FIXTURES ONLY.
    fn tier(t: Tier, worst: i64, typical: i64) -> TierRequirement {
        TierRequirement {
            tier: t,
            typical_month: usd(typical),
            worst_month: usd(worst),
            worst_month_name: "2026-07".to_string(),
            includes: Vec::new(),
            excludes: Vec::new(),
        }
    }

    fn ladder() -> ViableIncome {
        let tiers = vec![
            tier(Tier::Survival, 149_503, 149_503),
            tier(Tier::Current, 151_102, 151_102),
            tier(Tier::Stable, 160_000, 160_000),
            tier(Tier::Progress, 180_000, 180_000),
        ];
        ViableIncome {
            currency: Currency::USD,
            from: "2026-07-01".to_string(),
            to: "2026-10-31".to_string(),
            floor: tiers[0].clone(),
            headline: tiers[1].clone(),
            tiers,
            gaps: None,
            notes: Vec::new(),
        }
    }

    fn inputs(hours: f64) -> RateInputs {
        RateInputs { tax_fraction: 0.25, overheads_monthly: usd(20_000), ..RateInputs::new(hours, Currency::USD) }
    }

    #[test]
    fn the_rate_is_computed_from_billable_hours_and_not_from_hours_worked() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        // 20 billable hours over 46 weeks is 76.67 a month, NOT the 173 a full-time month suggests.
        assert!((f.billable_hours_per_month - 76.666_666).abs() < 0.001, "got {}", f.billable_hours_per_month);
        // current: (151102 + 20000) / 0.75 = 228136 a month to bill, over 76.67 hours = 2975/hr.
        assert_eq!(f.headline.must_bill_monthly.minor, 228_136);
        assert_eq!(f.headline.hourly.minor, 2_976, "rounded UP — a floor rounded down is below the floor");
        assert_eq!(f.headline.day_rate.minor, 2_976 * 8);

        // THE ERROR THIS EXISTS TO PREVENT: dividing by hours WORKED instead of billed. At 40 hours
        // the same need produces a rate roughly half as large, and the difference is the whole
        // margin between solvent and not.
        let naive = rate_floor(&ladder(), &inputs(40.0)).expect("computes");
        assert!(naive.headline.hourly.minor < f.headline.hourly.minor / 2 + 100);
        assert!(naive.headline.hourly.minor * 2 >= f.headline.hourly.minor - 100);
    }

    #[test]
    fn the_year_is_forty_six_weeks_because_the_gaps_are_unpaid() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert_eq!(inputs(20.0).working_weeks_per_year, 46.0);
        // Pricing on 52 weeks produces a lower rate, and the six weeks it assumes you will bill are
        // holidays, illness and the gaps between contracts.
        let optimistic = RateInputs { working_weeks_per_year: 52.0, ..inputs(20.0) };
        let o = rate_floor(&ladder(), &optimistic).expect("computes");
        assert!(o.headline.hourly.minor < f.headline.hourly.minor, "a longer year should lower the rate, making it easier to come up short");
    }

    #[test]
    fn contract_income_is_grossed_up_because_it_is_not_salary() {
        let none = RateInputs { tax_fraction: 0.0, overheads_monthly: usd(0), ..inputs(20.0) };
        let f0 = rate_floor(&ladder(), &none).expect("computes");
        let f1 = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert!(f1.headline.hourly.minor > f0.headline.hourly.minor, "tax and overheads must RAISE the floor");
        // And both omissions are said out loud rather than silently applied.
        assert!(f0.warnings.iter().any(|w| w.contains("too low by exactly that fraction")));
        assert!(f0.warnings.iter().any(|w| w.contains("health cover, equipment, software and accounting")));
    }

    #[test]
    fn the_ladder_of_rates_matches_the_ladder_of_needs() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert_eq!(f.tiers.len(), 4);
        // Each rate is at least the one below it, because each need is.
        assert!(f.tiers.windows(2).all(|w| w[1].hourly.minor >= w[0].hourly.minor));
        // CURRENT is the headline — the line below which new damage starts — and SURVIVAL is the
        // floor, below which working is not solving the problem.
        assert_eq!(f.headline.tier, Tier::Current);
        assert_eq!(f.floor.tier, Tier::Survival);
        assert!(f.floor.hourly.minor < f.headline.hourly.minor);
        assert!(summarise(&f).contains("keeps everything current"));
    }

    #[test]
    fn an_offer_below_the_floor_cannot_be_worked_harder_into_working() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        // A good offer: comfortably reachable inside the hours available.
        let good = assess_offer(&f, usd(6_000), Tier::Current).expect("assesses");
        assert!(good.reachable);
        assert!((good.hours_needed - 38.02).abs() < 0.1, "got {}", good.hours_needed);
        assert!(good.why.contains("it leaves"));

        // A bad one: no achievable number of hours reaches the tier. That is the sentence that
        // stops somebody grinding at a rate that cannot work.
        let bad = assess_offer(&f, usd(1_800), Tier::Current).expect("assesses");
        assert!(!bad.reachable);
        assert!(bad.hours_needed > f.billable_hours_per_month);
        assert!(bad.why.contains("working harder cannot close that, only a higher rate or a lower tier can"));

        // The same offer against a LOWER tier may still be reachable — which is the negotiation.
        let survival = assess_offer(&f, usd(2_400), Tier::Survival).expect("assesses");
        assert!(survival.hours_needed < assess_offer(&f, usd(2_400), Tier::Progress).unwrap().hours_needed);
    }

    #[test]
    fn inputs_that_cannot_support_a_rate_are_refused_rather_than_answered() {
        let l = ladder();
        // Guessing this is the whole error, so there is no default and zero is not one.
        let e = rate_floor(&l, &RateInputs::new(0.0, Currency::USD)).unwrap_err();
        assert!(e.contains("how many hours a week can you actually SELL"));
        assert!(rate_floor(&l, &RateInputs { working_weeks_per_year: 60.0, ..inputs(20.0) }).is_err());
        assert!(rate_floor(&l, &RateInputs { working_weeks_per_year: 0.0, ..inputs(20.0) }).is_err());
        // A "tax fraction" of 25 rather than 0.25 would silently produce a negative rate.
        let e2 = rate_floor(&l, &RateInputs { tax_fraction: 25.0, ..inputs(20.0) }).unwrap_err();
        assert!(e2.contains("it is a fraction, so 0.25 is 25%"));
        // And a currency mismatch is refused rather than added anyway.
        let eur = Currency::new("EUR").expect("code");
        assert!(rate_floor(&l, &RateInputs { overheads_monthly: money(1_000, eur), ..inputs(20.0) }).is_err());
        assert!(assess_offer(&rate_floor(&l, &inputs(20.0)).unwrap(), money(5_000, eur), Tier::Current).is_err());
        assert!(assess_offer(&rate_floor(&l, &inputs(20.0)).unwrap(), usd(0), Tier::Current).is_err());
    }

    #[test]
    fn every_assumption_that_drives_the_answer_is_written_down() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert_eq!(f.assumptions.len(), 4);
        assert!(f.assumptions[0].contains("Billable, not worked"));
        assert!(f.assumptions.iter().any(|a| a.contains("WORST month")));
        assert!(f.assumptions.iter().any(|a| a.contains("Rounded UP")));
        // A high billable figure is flagged, because it is the input most likely to be optimistic.
        let hopeful = rate_floor(&ladder(), &inputs(35.0)).expect("computes");
        assert!(hopeful.warnings.iter().any(|w| w.contains("is a high number to sustain")));
    }

    #[test]
    fn a_ladder_with_no_income_comparison_says_so() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert!(f.warnings.iter().any(|w| w.contains("nothing here knows how much of the floor you already clear")));
    }
}
